\begin{lemma}
\label{lem:1-13}



\dcref{ch1:1.13}
Let $\mathcal X$ be a locally finite family of subsets of a topological space
$M$. Then $\{\overline X:X\in\mathcal X\}$ is locally finite and
\[
\overline{\bigcup_{X\in\mathcal X}X}
=\bigcup_{X\in\mathcal X}\overline X.
\]
\end{lemma}

